func (this *Paradex) HandleMyTrade(client any, message map[string]any) {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "fills.ALL",
	//             "data": {
	//                 "id": "1718947571560201703986670001",
	//                 "side": "BUY",
	//                 "liquidity": "TAKER",
	//                 "market": "BTC-USD-PERP",
	//                 "order_id": "1718947571540201703992340000",
	//                 "price": "64852.9",
	//                 "size": "0.01",
	//                 "fee": "0.1945587",
	//                 "fee_currency": "USDC",
	//                 "created_at": 1718947571569,
	//                 "remaining_size": "0",
	//                 "client_id": "",
	//                 "fill_type": "FILL"
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	var trade map[string]any = ccxt.TradeToMap(this.ParseTrade(data))
	var symbol *string = this.SafeString(trade, "symbol")
	if this.MyTrades == nil {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		this.MyTrades = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var trades ccxt.WsArrayCache = this.MyTrades
	trades.Append(trade)
	var messageHash string = "myTrades"
	client.(ccxt.ClientInterface).Resolve(trades, messageHash)
	if symbol != nil {
		client.(ccxt.ClientInterface).Resolve(trades, messageHash+":"+*symbol)
	}
}

/**
 * @method
 * @name paradex#watchPositions
 * @description watch all open positions
 * @see https://docs.paradex.trade/ws/web-socket-channels/positions/positions
 * @param {string[]} [symbols] list of unified market symbols
 * @param {int} [since] the earliest time in ms to fetch positions for
 * @param {int} [limit] the maximum number of positions to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/?id=position-structure}
 */
func (this *Paradex) WatchPositionsAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[[]ccxt.Position] {
	ch := make(chan ccxt.AsyncResult[[]ccxt.Position], 1)
	go this.watchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Paradex) watchPositionsBody(ch chan ccxt.AsyncResult[[]ccxt.Position], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbols []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.AuthenticateAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	// one channel carries every market
	var channel string = "positions"
	var url any = this.GetWsUrl()
	var messageHashes []any = []any{}
	var symbolsLength int = 0
	if symbolsNormalized != nil {
		symbolsLength = len(symbolsNormalized)
	}
	if symbolsLength == 0 {
		messageHashes = append(messageHashes, channel)
	} else {
		for i := 0; i < symbolsLength; i++ {
			messageHashes = append(messageHashes, ccxt.Add(channel+":", func() any {
				if i >= 0 && i < len(symbolsNormalized) {
					return symbolsNormalized[i]
				}
				return nil
			}()))
		}
	}
	var request map[string]any = this.SubscribeRequest(channel)
	var subscription map[string]any = map[string]any{
		"id":            request["id"],
		"messageHashes": messageHashes,
	}

	r2 := <-this.WatchMultiple(url, messageHashes, this.DeepExtend(request, params), []any{channel}, subscription)
	if r2.Err != nil {
		panic(r2.Err)
	}
	newPositions := r2.Value
	if this.NewUpdates {

		var resolved []any
		switch resolvedBox := newPositions.(type) {
		case []any:
			resolved = resolvedBox
		case ccxt.IArrayCache:
			resolved = resolvedBox.ToArray()
		case nil:
		default:
			panic(ccxt.ExchangeError("resolved value is not []any"))
		}
		ch <- ccxt.AsyncResult[[]ccxt.Position]{Value: ccxt.PositionsFromList(resolved)}
		return nil
	}

	ch <- ccxt.AsyncResult[[]ccxt.Position]{Value: ccxt.PositionsFromList(this.FilterBySymbolsSinceLimit(this.Positions, symbolsNormalized, since, limit, true))}
	return nil
}
func (this *Paradex) HandlePositions(client any, message map[string]any) {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "positions",
	//             "data": {
	//                 "id": "0x49ddd7a564c978f6e4089ff8355b56a42b7e2d48ba282cb5aad60f04bea0ec3-BTC-USD-PERP",
	//                 "market": "BTC-USD-PERP",
	//                 "status": "OPEN",
	//                 "side": "LONG",
	//                 "size": "0.01",
	//                 "average_entry_price": "64839.96053748",
	//                 "unrealized_pnl": "-2.39677214",
	//                 "leverage": "5",
	//                 "cost_usd": "648.529",
	//                 "created_at": 1718947571560,
	//                 "last_updated_at": 1718950074249,
	//                 "liquidation_price": ""
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	if this.Positions == nil {
		this.Positions = ccxt.NewArrayCacheBySymbolBySide()
	}
	var cache ccxt.WsArrayCache = this.Positions
	var position map[string]any = ccxt.PositionToMap(this.ParsePosition(data))
	var symbol *string = ccxt.SafeStringPtr(position["symbol"])
	var newPositions []any = []any{}
	// one position per market, so a fill through zero flips its side: the cache keys by
	// symbol and side, and the opposite side it still holds is flattened here
	var side *string = this.SafeString(position, "side")
	var cached []any = this.FilterBySymbolSinceLimit(cache, symbol, nil, nil, true)
	for i := 0; i < len(cached); i++ {
		var previous any = cached[i]
		var previousSide *string = this.SafeString(previous, "side")
		var previousContracts *string = this.SafeString(previous, "contracts")
		var isOpposite bool = (side != nil) && (previousSide != nil) && (previousSide != side && (previousSide == nil || side == nil || *previousSide != *side))
		if isOpposite && (previousContracts != nil) && !ccxt.Precise.StringEq(previousContracts, "0") {
			var flattened map[string]any = this.Extend(previous, map[string]any{
				"contracts":           this.ParseNumber("0"),
				"lastUpdateTimestamp": this.SafeInteger(position, "lastUpdateTimestamp"),
			})
			cache.Append(flattened)
			newPositions = append(newPositions, flattened)
		}
	}
	cache.Append(position)
	newPositions = append(newPositions, position)
	client.(ccxt.ClientInterface).Resolve(newPositions, "positions")
	client.(ccxt.ClientInterface).Resolve(newPositions, ccxt.Add("positions:", symbol))
}

/**
 * @method
 * @name paradex#watchBalance
 * @description watch the margin balance of the account in its settlement asset: total is the account
 * value, free the free collateral and used the initial margin requirement
 * @see https://docs.paradex.trade/ws/web-socket-channels/account/account
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Paradex) WatchBalanceAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[ccxt.Balances] {
	ch := make(chan ccxt.AsyncResult[ccxt.Balances], 1)
	go this.watchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Paradex) watchBalanceBody(ch chan ccxt.AsyncResult[ccxt.Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.AuthenticateAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var channel string = "account"
	var url any = this.GetWsUrl()
	var messageHash string = "balance"
	var request map[string]any = this.SubscribeRequest(channel)
	var subscription map[string]any = map[string]any{
		"id":            request["id"],
		"messageHashes": []any{messageHash},
	}

	r2 := <-this.Watch(url, messageHash, this.DeepExtend(request, params), channel, subscription)
	if r2.Err != nil {
		panic(r2.Err)
	}
	ch <- ccxt.AsyncResult[ccxt.Balances]{Value: ccxt.BalancesFromMap(r2.Value)}
	return nil
}
func (this *Paradex) HandleBalance(client any, message map[string]any) {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "account",
	//             "data": {
	//                 "account": "0x4638e3041366aa71720be63e32e53e1223316c7f0d56f7aa617542ed1e7512b",
	//                 "account_value": "1000.5",
	//                 "free_collateral": "900.5",
	//                 "initial_margin_requirement": "100",
	//                 "maintenance_margin_requirement": "50",
	//                 "margin_cushion": "950.5",
	//                 "seq_no": 20,
	//                 "settlement_asset": "USDC",
	//                 "status": "ACTIVE",
	//                 "total_collateral": "1000",
	//                 "updated_at": 1718950074249
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	// merge the parsed update into the existing balance object instead of
	// replacing it: a consumer awakened by an earlier message holds a
	// reference to this.balance, and ccxt.Client.resolve is a no-op while
	// nobody is awaiting, so a replaced object would make updates landing
	// in that window invisible to the consumer forever (same class as
	// issue #26773); the free/used/total aggregates are rebuilt from the
	// merged currencies by safeBalance
	var balance any = this.ParseWsBalance(data)
	if this.Balance == nil {
		this.Balance = map[string]any{}
	}
	var reserved []any = []any{"free", "used", "total"}
	var keys []string = ccxt.ObjectKeys(balance)
	for i := 0; i < len(keys); i++ {
		var key string = keys[i]
		if this.InArray(key, reserved) {
			continue
		}
		this.Balance[key] = ccxt.GetValue(balance, key)
	}
	this.Balance, _ = this.SafeBalance(this.Balance).(map[string]any)
	client.(ccxt.ClientInterface).Resolve(this.Balance, "balance")
}
func (this *Paradex) ParseWsBalance(data map[string]any) any {
	// the account channel carries margin, not token holdings: the account value (collateral with
	// unrealized pnl) is the total, the free collateral what can still back a new position, and the
	// initial margin the part the open positions hold, free + used = total as the venue computes them
	var timestamp *int64 = this.SafeInteger(data, "updated_at")
	var result map[string]any = map[string]any{
		"info":      data,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
	var code *string = this.SafeCurrencyCode(this.SafeString(data, "settlement_asset"))
	var account map[string]any = this.Account()
	account["total"] = this.SafeString(data, "account_value")
	account["free"] = this.SafeString(data, "free_collateral")
	account["used"] = this.SafeString(data, "initial_margin_requirement")
	if code != nil {
		result[*code] = account
	}
	return this.SafeBalance(result)
}
func (this *Paradex) HandleTicker(client any, message map[string]any) any {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "markets_summary",
	//             "data": {
	//                 "symbol": "ORDI-USD-PERP",
	//                 "oracle_price": "49.80885481",
	//                 "mark_price": "49.80885481",
	//                 "last_traded_price": "62.038",
	//                 "bid": "49.822",
	//                 "ask": "58.167",
	//                 "volume_24h": "0",
	//                 "total_volume": "54542628.66054200416",
	//                 "created_at": 1718334307698,
	//                 "underlying_price": "47.93",
	//                 "open_interest": "6999.5",
	//                 "funding_rate": "0.03919997509811",
	//                 "price_change_rate_24h": ""
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	var marketId *string = this.SafeString(data, "symbol")
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var channel *string = this.SafeString(params, "channel")
	var ticker map[string]any = ccxt.TickerToMap(this.ParseTicker(data, market))
	if symbol != nil {
		this.Tickers[*symbol] = ccxt.TickerFromMap(ticker)
	}
	client.(ccxt.ClientInterface).Resolve(ticker, channel)
	// watchTicker waits on the symbol whichever channel, per-market or all, carried it
	var messageHash string = "markets_summary." + *symbol
	client.(ccxt.ClientInterface).Resolve(ticker, messageHash)
	return message
}

/**
 * @method
 * @name paradex#watchFundingRate
 * @description watch the current funding rate for a symbol
 * @see https://docs.paradex.trade/ws/web-socket-channels/funding-data-market-symbol/funding-data-market-symbol
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [funding rate structure]{@link https://docs.ccxt.com/?id=funding-rate-structure}
 */
func (this *Paradex) WatchFundingRateAsync(symbol string, optionalArgs ...any) <-chan ccxt.AsyncResult[ccxt.FundingRate] {
	ch := make(chan ccxt.AsyncResult[ccxt.FundingRate], 1)
	go this.watchFundingRateBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Paradex) watchFundingRateBody(ch chan ccxt.AsyncResult[ccxt.FundingRate], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	// the per-market channel, the all-markets one sends every perpetual's funding
	var channel *string = ccxt.SafeStringPtr(ccxt.Add("funding_data.", market["id"]))
	var url any = this.GetWsUrl()
	// its own hash: funding_data.<symbol> is the hash of watchFundingRates on the all-markets channel
	var messageHash *string = ccxt.SafeStringPtr("fundingRate:" + market["symbol"].(string))

	r1 := <-this.SubscribeChannelsAsync(url, []any{messageHash}, []any{channel}, params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	ch <- ccxt.AsyncResult[ccxt.FundingRate]{Value: ccxt.FundingRateFromMap(r1.Value)}
	return nil
}

/**
 * @method
 * @name paradex#unWatchFundingRate
 * @description unsubscribes from the funding data channel of a market
 * @see https://docs.paradex.trade/ws/web-socket-channels/funding-data-market-symbol/funding-data-market-symbol
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {boolean} true once unsubscribed
 */
func (this *Paradex) UnWatchFundingRateAsync(symbol string, optionalArgs ...any) <-chan ccxt.AsyncResult[bool] {
	ch := make(chan ccxt.AsyncResult[bool], 1)
	go this.unWatchFundingRateBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Paradex) unWatchFundingRateBody(ch chan ccxt.AsyncResult[bool], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var channel *string = ccxt.SafeStringPtr(ccxt.Add("funding_data.", market["id"]))
	var messageHash *string = ccxt.SafeStringPtr("fundingRate:" + market["symbol"].(string))

	r1 := <-this.UnsubscribeChannelsAsync(this.GetWsUrl(), "fundingRate", []any{channel}, []any{messageHash}, []any{market["symbol"]}, params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var resolved bool
	switch resolvedBox := r1.Value.(type) {
	case bool:
		resolved = resolvedBox
	case []any:
		resolved = len(resolvedBox) > 0
	case map[string]any:
		resolved = true
	case nil:
	default:
		panic(ccxt.ExchangeError("resolved value is not bool"))
	}
	ch <- ccxt.AsyncResult[bool]{Value: resolved}
	return nil
}

/**
 * @method
 * @name paradex#watchFundingRates
 * @description watch the funding rate for multiple markets
 * @see https://docs.paradex.trade/ws/web-socket-channels/markets-summary-market-symbol/markets-summary-market-symbol
 * @param {string[]} [symbols] a list of unified market symbols
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [funding rate structure]{@link https://docs.ccxt.com/?id=funding-rate-structure}
 */
func (this *Paradex) WatchFundingRatesAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[map[string]ccxt.FundingRate] {
	ch := make(chan ccxt.AsyncResult[map[string]ccxt.FundingRate], 1)
	go this.watchFundingRatesBody(ch, optionalArgs...)
	return ch
}
func (this *Paradex) watchFundingRatesBody(ch chan ccxt.AsyncResult[map[string]ccxt.FundingRate], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbols []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var channel string = "funding_data"
	var url any = this.GetWsUrl()
	var messageHashes []any = []any{}
	if symbolsNormalized != nil {
		var symbolsLength int = len(symbolsNormalized)
		if symbolsLength > 0 {
			for i := 0; i < len(symbolsNormalized); i++ {
				var messageHash string = channel + "." + symbolsNormalized[i]
				messageHashes = append(messageHashes, messageHash)
			}
		} else {
			messageHashes = append(messageHashes, channel) // if an empty array is passed, subscribe to all funding rates
		}
	} else {
		messageHashes = append(messageHashes, channel)
	}
	var request map[string]any = this.SubscribeRequest(channel)
	var subscription map[string]any = map[string]any{
		"id": request["id"],
	}

	r1 := <-this.WatchMultiple(url, messageHashes, this.DeepExtend(request, params), messageHashes, subscription)
	if r1.Err != nil {
		panic(r1.Err)
	}
	newFundingRates := r1.Value
	if this.NewUpdates {
		var result map[string]any = map[string]any{}
		var newFundingRatesSymbol *string = this.SafeString(newFundingRates, "symbol")
		if newFundingRatesSymbol != nil {
			ccxt.AddElementToObject(result, newFundingRatesSymbol, newFundingRates)
		}

		ch <- ccxt.AsyncResult[map[string]ccxt.FundingRate]{Value: ccxt.FundingRateMapFromMap(result)}
		return nil
	}

	ch <- ccxt.AsyncResult[map[string]ccxt.FundingRate]{Value: ccxt.FundingRateMapFromMap(this.FilterByArray(this.FundingRates, "symbol", symbolsNormalized))}
	return nil
}
func (this *Paradex) HandleFundingRate(client any, message map[string]any) {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "funding_data",
	//             "data": {
	//                 "market": "TRUMP-USD-PERP",
	//                 "funding_index": "-0.551694014226244835",
	//                 "funding_premium": "-0.000509914923994872836",
	//                 "funding_rate": "-0.00014969570582",
	//                 "funding_rate_8h": "-0.00014969",
	//                 "funding_period_hours": 8,
	//                 "created_at": 1771506636154
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	var fundingRate any = this.ParseFundingRateWs(data)
	var symbol *string = this.SafeString(fundingRate, "symbol")
	ccxt.AddElementToObject(this.FundingRates, symbol, fundingRate)
	// watchFundingRates waits on the bare channel without symbols and on funding_data.<symbol> with them,
	// watchFundingRate on fundingRate:<symbol>, the per-market and all-markets channels carry the same frame
	client.(ccxt.ClientInterface).Resolve(fundingRate, "funding_data")
	client.(ccxt.ClientInterface).Resolve(fundingRate, ccxt.Add("funding_data.", symbol))
	client.(ccxt.ClientInterface).Resolve(fundingRate, ccxt.Add("fundingRate:", symbol))
}
func (this *Paradex) ParseFundingRateWs(contract map[string]any, optionalArgs ...any) any {
	//
	//     {
	//         "market": "TRUMP-USD-PERP",
	//         "funding_index": "-0.551694014226244835",
	//         "funding_premium": "-0.000509914923994872836",
	//         "funding_rate": "-0.00014969570582",
	//         "funding_rate_8h": "-0.00014969",
	//         "funding_period_hours": 8,
	//         "created_at": 1771506636154
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(contract, "market")
	var symbol *string = this.SafeSymbol(marketId, market)
	var timestamp *int64 = this.SafeInteger(contract, "created_at")
	var fundingPeriod *string = this.SafeString(contract, "funding_period_hours")
	var interval *string = nil
	if fundingPeriod != nil {
		interval = ccxt.SafeStringPtr(*fundingPeriod + "h")
	}
	return map[string]any{
		"info":                     contract,
		"symbol":                   symbol,
		"markPrice":                nil,
		"indexPrice":               nil,
		"interestRate":             this.ParseNumber("0"),
		"estimatedSettlePrice":     nil,
		"timestamp":                timestamp,
		"datetime":                 this.Iso8601(timestamp),
		"fundingRate":              this.SafeNumber(contract, "funding_rate"),
		"fundingTimestamp":         nil,
		"fundingDatetime":          nil,
		"nextFundingRate":          nil,
		"nextFundingTimestamp":     nil,
		"nextFundingDatetime":      nil,
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
		"interval":                 interval,
	}
}
func (this *Paradex) ParseSbeMessage(client any, message any) any {
	//
	// Paradex SBE schema 1:3 (https://docs.paradex.trade), little-endian. Every frame is an 8-byte
	// header (blockLength, templateId, schemaId, version as uint16) followed by a fixed block of
	// blockLength bytes, then repeating groups and length-prefixed strings. The frame is rebuilt in
	// the shape of the matching JSON subscription message, so the JSON handlers parse both.
	// Requests, subscribe acks and errors stay JSON text frames.
	//
	// Returns undefined for frames that carry nothing to route: heartbeats, binary acks, template
	// ids this decoder does not know (the schema says to skip them), and malformed frames.
	//
	var frameHex string = this.BinaryToBase16(message)
	var frameLength int64 = this.ParseToInt(float64(len(frameHex)) / 2)
	if frameLength < 8 {
		return nil
	}
	var blockLength int64 = this.ParseToInt(this.SbeReadUint(frameHex, 0, 2))
	var templateId int64 = this.ParseToInt(this.SbeReadUint(frameHex, 2, 2))
	var schemaId int64 = this.ParseToInt(this.SbeReadUint(frameHex, 4, 2))
	if (schemaId != 1) || (frameLength < (blockLength + 8)) {
		return nil
	}
	var channel *string = nil
	var data any = nil
	if templateId == 1 {
		data = this.ParseSbeTrade(frameHex, blockLength, frameLength)
		if !ccxt.IsEqual(data, nil) {
			channel = ccxt.SafeStringPtr("trades." + *this.SafeString(data, "market", ""))
		}
	} else if templateId == 2 {
		data = this.ParseSbeBbo(frameHex, blockLength, frameLength)
		if !ccxt.IsEqual(data, nil) {
			channel = ccxt.SafeStringPtr("bbo." + *this.SafeString(data, "market", ""))
		}
	} else if templateId == 3 {
		// the snapshot and deltas feeds send the same frame, handleOrderBook tells them apart by package type
		data = this.ParseSbeOrderBook(frameHex, blockLength, frameLength)
		if !ccxt.IsEqual(data, nil) {
			channel = ccxt.SafeStringPtr("order_book." + *this.SafeString(data, "market", ""))
		}
	} else if templateId == 4 {
		data = this.ParseSbeMarketSummary(client, frameHex, blockLength, frameLength)
		channel = ccxt.SafeStringPtr("markets_summary")
	} else if templateId == 5 {
		data = this.ParseSbeFundingData(frameHex, blockLength, frameLength)
		channel = ccxt.SafeStringPtr("funding_data")
	} else if templateId == 20 {
		data = this.ParseSbeOrder(frameHex, blockLength, frameLength)
		if !ccxt.IsEqual(data, nil) {
			channel = ccxt.SafeStringPtr("orders." + *this.SafeString(data, "market", ""))
		}
	} else if templateId == 21 {
		data = this.ParseSbeFill(frameHex, blockLength, frameLength)
		if !ccxt.IsEqual(data, nil) {
			channel = ccxt.SafeStringPtr("fills." + *this.SafeString(data, "market", ""))
		}
	} else if templateId == 22 {
		data = this.ParseSbePosition(frameHex, blockLength, frameLength)
		channel = ccxt.SafeStringPtr("positions")
	} else if templateId == 23 {
		data = this.ParseSbeAccount(frameHex, blockLength, frameLength)
		channel = ccxt.SafeStringPtr("account")
	}
	if ccxt.IsEqual(data, nil) {
		return nil
	}
	return map[string]any{
		"sbe": true,
		"params": map[string]any{
			"channel": channel,
			"data":    data,
		},
	}
}
func (this *Paradex) SbeReadUint(frameHex string, offset any, length any) any {
	// a little-endian unsigned integer of at most 4 bytes, so that it stays exact in every language
	var digits string = "0123456789abcdef"
	var result any = 0
	var factor int64 = 1
	var count int64 = this.ParseToInt(length)
	var start int64 = this.ParseToInt(offset)
	var position int64 = start * 2
	for i := 0; int64(i) < count; i++ {
		// plain variables as slice bounds, php gets end - start unparenthesized
		var middle int64 = position + 1
		var next int64 = position + 2
		var high int = strings.Index(digits, ccxt.Slice(frameHex, position, middle))
		var low int = strings.Index(digits, ccxt.Slice(frameHex, middle, next))
		result = this.ParseToInt(this.Sum(result, ccxt.Multiply(high*16, factor), (int64(low) * factor)))
		factor = this.ParseToInt(factor * 256)
		position = this.ParseToInt(next)
	}
	// an exact integer below 2^32, parseToInt keeps it and types the return as an integer
	return this.ParseToInt(result)
}
func (this *Paradex) SbeReadInt64(frameHex string, offset any) any {
	// a signed int64 as a decimal string, undefined for INT64_MIN which the schema uses as null
	var low int64 = this.ParseToInt(this.SbeReadUint(frameHex, offset, 4))
	var high int64 = this.ParseToInt(this.SbeReadUint(frameHex, this.Sum(offset, 4), 4))
	if (high == 2147483648) && (low == 0) {
		return nil
	}
	if high == 0 {
		return this.NumberToString(low)
	}
	var result *string = ccxt.Precise.StringAdd(ccxt.Precise.StringMul(this.NumberToString(high), "4294967296"), this.NumberToString(low))
	if high >= 2147483648 {
		result = ccxt.Precise.StringSub(result, "18446744073709551616")
	}
	return result
}
func (this *Paradex) SbeReadDecimal(frameHex string, offset any) any {
	// prices, sizes and rates are int64 mantissas with a fixed exponent of -8
	var mantissa any = this.SbeReadInt64(frameHex, offset)
	if mantissa == nil {
		return nil
	}
	return ccxt.Precise.StringDiv(mantissa, "100000000", 8)
}
func (this *Paradex) SbeReadTimestamp(frameHex string, offset any) any {
	// timestamps are microseconds, truncated to milliseconds with ccxt.Precise: a float
	// quotient like 1791906071000.999 is rounded up when php converts it to an int
	var microseconds any = this.SbeReadInt64(frameHex, offset)
	if microseconds == nil {
		return nil
	}
	return this.ParseToInt(ccxt.Precise.StringDiv(microseconds, "1000", 0))
}
func (this *Paradex) SbeReadEnum(frameHex string, offset any, values map[string]any) *string {
	var value int64 = this.ParseToInt(this.SbeReadUint(frameHex, offset, 1))
	return this.SafeString(values, this.NumberToString(value))
}
func (this *Paradex) SbeReadString(frameHex string, offset int64, length int64) string {
	var first int64 = this.ParseToInt(offset)
	var size int64 = this.ParseToInt(length)
	var start int64 = first * 2
	var end any = this.Sum(start, size*2)
	return this.BinaryToString(this.Base16ToBinary(ccxt.Slice(frameHex, start, end)))
}
func (this *Paradex) SbeReadAddress(frameHex string, offset any) string {
	// a 32-byte big-endian account address, printed without leading zeros like the JSON feed
	var first int64 = this.ParseToInt(offset)
	var rawStart int64 = first * 2
	var rawEnd int64 = rawStart + 64
	var raw string = ccxt.Slice(frameHex, rawStart, rawEnd)
	var start any = 63
	for i := 0; i < 63; i++ {
		var next int = i + 1
		if ccxt.Slice(raw, i, next) != "0" {
			start = i
			break
		}
	}
	return "0x" + ccxt.Slice(raw, start, 64)
}
func (this *Paradex) SbeReadVarStrings(frameHex string, offset any, count any, frameLength int64) []any {
	// the var-data section: count strings, each prefixed with a uint8 length. Returns an empty list
	// when the frame ends before all of them, and only the strings present when a trailing one is
	// absent, which is how a field appended to var-data reads on a frame from before it.
	// Every caller guards on the count it needs, so an empty list and a short one read alike
	var result []any = []any{}
	var end int64 = this.ParseToInt(frameLength)
	var total int64 = this.ParseToInt(count)
	var position int64 = this.ParseToInt(offset)
	for i := 0; int64(i) < total; i++ {
		if position >= end {
			return result
		}
		var length int64 = this.ParseToInt(this.SbeReadUint(frameHex, position, 1))
		var next int64 = this.ParseToInt(this.Sum(position, 1, length))
		if next > end {
			return []any{}
		}
		result = append(result, this.SbeReadString(frameHex, position+1, length))
		position = next
	}
	return result
}
func (this *Paradex) ParseSbeTrade(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// TradeEvent (templateId 1), 50-byte block
	//
	//     ts int64, seq int64, tradeId int64 (deprecated, truncated), side uint8, price int64,
	//     size int64, createdAt int64, tradeType uint8, then market and tradeIdStr strings
	//
	if blockSize < 50 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 2, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 1 {
		return nil
	}
	var sides map[string]any = map[string]any{
		"1": "BUY",
		"2": "SELL",
	}
	var tradeTypes map[string]any = map[string]any{
		"1": "FILL",
		"2": "LIQUIDATION",
		"3": "UNWIND_TRANSFER",
		"4": "SETTLE_MARKET",
		"5": "RPI",
		"6": "BLOCK_TRADE",
	}
	return map[string]any{
		"id":         this.SafeString(strings, 1),
		"market":     this.SafeString(strings, 0),
		"side":       this.SbeReadEnum(frameHex, 32, sides),
		"size":       this.SbeReadDecimal(frameHex, 41),
		"price":      this.SbeReadDecimal(frameHex, 33),
		"created_at": this.SbeReadTimestamp(frameHex, 49),
		"trade_type": this.SbeReadEnum(frameHex, 57, tradeTypes),
	}
}
func (this *Paradex) ParseSbeBbo(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// BboEvent (templateId 2), 48-byte block
	//
	//     ts int64, seq int64, bidPrice int64, bidSize int64, askPrice int64, askSize int64 (each price
	//     and size null on an empty side), then the market string
	//
	if blockSize < 48 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 1, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 1 {
		return nil
	}
	return map[string]any{
		"market":          this.SafeString(strings, 0),
		"seq_no":          this.SbeReadInt64(frameHex, 16),
		"bid":             this.SbeReadDecimal(frameHex, 24),
		"bid_size":        this.SbeReadDecimal(frameHex, 32),
		"ask":             this.SbeReadDecimal(frameHex, 40),
		"ask_size":        this.SbeReadDecimal(frameHex, 48),
		"last_updated_at": this.SbeReadTimestamp(frameHex, 8),
	}
}
func (this *Paradex) ParseSbeOrderBook(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// BookEvent (templateId 3), 89-byte block
	//
	//     ts int64, seq int64, pkgType uint8 (0 snapshot, 1 delta), nine best bid/ask int64 fields, then
	//     the bids and asks groups of (price int64, size int64) entries and the market string. A delta
	//     carries the changed levels, a size of 0 removes the level
	//
	if blockSize < 17 {
		return nil
	}
	var pkgType int64 = this.ParseToInt(this.SbeReadUint(frameHex, 24, 1))
	if (pkgType != 0) && (pkgType != 1) {
		return nil
	}
	var levels []any = []any{}
	var sides []string = []string{"BUY", "SELL"}
	var frameEnd int64 = this.ParseToInt(frameLength)
	var position int64 = this.ParseToInt(this.Sum(blockLength, 8))
	for i := 0; i < len(sides); i++ {
		if (position + 4) > frameEnd {
			return nil
		}
		var entryLength int64 = this.ParseToInt(this.SbeReadUint(frameHex, position, 2))
		var numInGroup int64 = this.ParseToInt(this.SbeReadUint(frameHex, position+2, 2))
		position = this.ParseToInt(position + 4)
		if (entryLength < 16) || (this.ParseToInt(this.Sum(position, numInGroup*entryLength)) > frameEnd) {
			return nil
		}
		for j := 0; int64(j) < numInGroup; j++ {
			levels = append(levels, map[string]any{
				"side":  sides[i],
				"price": this.SbeReadDecimal(frameHex, position),
				"size":  this.SbeReadDecimal(frameHex, position+8),
			})
			position = this.ParseToInt(this.Sum(position, entryLength))
		}
	}
	var strings []any = this.SbeReadVarStrings(frameHex, position, 1, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 1 {
		return nil
	}
	var isSnapshot bool = (pkgType == 0)
	return map[string]any{
		"seq_no":          this.SbeReadInt64(frameHex, 16),
		"market":          this.SafeString(strings, 0),
		"last_updated_at": this.SbeReadTimestamp(frameHex, 8),
		"update_type": func() string {
			if isSnapshot {
				return "s"
			}
			return "d"
		}(),
		"inserts": func() any {
			if isSnapshot {
				return levels
			}
			return []any{}
		}(),
		"updates": func() any {
			if isSnapshot {
				return []any{}
			}
			return levels
		}(),
		"deletes": []any{},
	}
}
func (this *Paradex) ParseSbeMarketSummary(client any, frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// MarketSummaryEvent (templateId 4), 248-byte block (240 before 1:3), of which the first
	// 12 int64 fields and settlementTwapEstimate are read
	//
	//     ts, seq, markPrice, indexPrice, lastPrice, volumeUsd24h, openInterest, fundingRate, bid,
	//     ask, totalVolume, priceChangeRate24h, ..., settlementTwapEstimate (1:3, at 240), then the
	//     market string
	//
	if blockSize < 96 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 1, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 1 {
		return nil
	}
	// the market is read first, so that a frame for a market nobody subscribed to is dropped before its
	// decimals are decoded, like one still in flight after its market left the scoped filter
	var marketId *string = this.SafeString(strings, 0, "")
	var subscribeHash string = "markets_summary." + *marketId
	if !(client.(ccxt.ClientInterface).SubscriptionHas("markets_summary")) && !(client.(ccxt.ClientInterface).SubscriptionHas(subscribeHash)) {
		return nil
	}
	// appended in 1:3: null outside the pre-expiry settlement window and for undated markets
	var settlementTwapEstimate any = nil
	if blockSize >= 248 {
		settlementTwapEstimate = this.SbeReadDecimal(frameHex, 248)
	}
	return map[string]any{
		"symbol":                   marketId,
		"mark_price":               this.SbeReadDecimal(frameHex, 24),
		"last_traded_price":        this.SbeReadDecimal(frameHex, 40),
		"bid":                      this.SbeReadDecimal(frameHex, 72),
		"ask":                      this.SbeReadDecimal(frameHex, 80),
		"volume_24h":               this.SbeReadDecimal(frameHex, 48),
		"total_volume":             this.SbeReadDecimal(frameHex, 88),
		"created_at":               this.SbeReadTimestamp(frameHex, 8),
		"open_interest":            this.SbeReadDecimal(frameHex, 56),
		"funding_rate":             this.SbeReadDecimal(frameHex, 64),
		"price_change_rate_24h":    this.SbeReadDecimal(frameHex, 96),
		"settlement_twap_estimate": settlementTwapEstimate,
	}
}
func (this *Paradex) ParseSbeFundingData(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// FundingDataEvent (templateId 5), 66-byte block
	//
	//     ts int64, seq int64, fundingRate int64, fundingIndex int64, createdAt int64,
	//     fundingPremium int64, fundingRate8h int64, fundingPeriodHours int16, ... then the market
	//
	if blockSize < 58 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 1, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 1 {
		return nil
	}
	return map[string]any{
		"market":               this.SafeString(strings, 0),
		"funding_index":        this.SbeReadDecimal(frameHex, 32),
		"funding_premium":      this.SbeReadDecimal(frameHex, 48),
		"funding_rate":         this.SbeReadDecimal(frameHex, 24),
		"funding_rate_8h":      this.SbeReadDecimal(frameHex, 56),
		"funding_period_hours": this.SbeReadUint(frameHex, 64, 2),
		"created_at":           this.SbeReadTimestamp(frameHex, 40),
	}
}
func (this *Paradex) ParseSbeOrder(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// OrderEvent (templateId 20), 128-byte block (126 before the 1:2 request fields)
	//
	//     ts int64, seq int64, status uint8, side uint8, orderType uint8, timeInForce uint8,
	//     price int64, triggerPrice int64, size int64, sizeOpen int64, avgFillPrice int64,
	//     createdAt int64, updatedAt int64, account [32]byte, receivedAt int64, publishedAt int64,
	//     stp uint8, flags uint8, ... then the orderId, clientOrderId, market and cancelReason strings
	//
	if blockSize < 126 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 4, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 4 {
		return nil
	}
	var statuses map[string]any = map[string]any{
		"1": "NEW",
		"2": "UNTRIGGERED",
		"3": "OPEN",
		"4": "CLOSED",
	}
	var sides map[string]any = map[string]any{
		"1": "BUY",
		"2": "SELL",
	}
	var orderTypes map[string]any = map[string]any{
		"1": "LIMIT",
		"2": "MARKET",
		"3": "STOP_LIMIT",
		"4": "STOP_MARKET",
		"5": "TAKE_PROFIT_LIMIT",
		"6": "TAKE_PROFIT_MARKET",
		"7": "STOP_LOSS_LIMIT",
		"8": "STOP_LOSS_MARKET",
	}
	var timeInForces map[string]any = map[string]any{
		"1": "GTC",
		"2": "IOC",
		"3": "POST_ONLY",
		"4": "RPI",
	}
	var stpModes map[string]any = map[string]any{
		"0": "NONE",
		"1": "EXPIRE_MAKER",
		"2": "EXPIRE_TAKER",
		"3": "EXPIRE_BOTH",
	}
	var flags []any = this.SbeReadFlags(frameHex, 133, []any{"REDUCE_ONLY", "STOP_CONDITION_BELOW_TRIGGER", "STOP_CONDITION_ABOVE_TRIGGER", "INTERACTIVE", "TARGET_STRATEGY_VWAP", "MMP"})
	var order map[string]any = map[string]any{
		"account":         this.SbeReadAddress(frameHex, 84),
		"avg_fill_price":  this.SbeReadDecimal(frameHex, 60),
		"client_id":       this.SafeString(strings, 1),
		"created_at":      this.SbeReadTimestamp(frameHex, 68),
		"flags":           flags,
		"id":              this.SafeString(strings, 0),
		"instruction":     this.SbeReadEnum(frameHex, 27, timeInForces),
		"last_updated_at": this.SbeReadTimestamp(frameHex, 76),
		"market":          this.SafeString(strings, 2),
		"price":           this.SbeReadDecimal(frameHex, 28),
		"published_at":    this.SbeReadTimestamp(frameHex, 124),
		"received_at":     this.SbeReadTimestamp(frameHex, 116),
		"remaining_size":  this.SbeReadDecimal(frameHex, 52),
		"seq_no":          this.SbeReadInt64(frameHex, 16),
		"side":            this.SbeReadEnum(frameHex, 25, sides),
		"size":            this.SbeReadDecimal(frameHex, 44),
		"status":          this.SbeReadEnum(frameHex, 24, statuses),
		"stp":             this.SbeReadEnum(frameHex, 132, stpModes),
		"timestamp":       this.SbeReadTimestamp(frameHex, 8),
		"trigger_price":   this.SbeReadDecimal(frameHex, 36),
		"type":            this.SbeReadEnum(frameHex, 26, orderTypes),
	}
	// an empty cancel reason is sent for every live order, parseOrder reads any reason as canceled
	var cancelReason *string = this.SafeString(strings, 3, "")
	if cancelReason == nil || *cancelReason != "" {
		order["cancel_reason"] = cancelReason
	}
	return order
}
func (this *Paradex) SbeReadFlags(frameHex string, offset any, names any) []any {
	// a uint8 bitset, names[bit] for each set bit, an empty name for a bit the schema leaves unused
	var flags []any = []any{}
	var bits int64 = this.ParseToInt(this.SbeReadUint(frameHex, offset, 1))
	for i := 0; i < ccxt.GetArrayLength(names); i++ {
		var bit int64 = this.ParseToInt(bits % 2)
		if (bit == 1) && (ccxt.GetValue(names, i) != "") {
			flags = append(flags, ccxt.GetValue(names, i))
		}
		bits = this.ParseToInt(float64(bits) / 2)
	}
	return flags
}
func (this *Paradex) ParseSbeFill(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// FillEvent (templateId 21), 116-byte block (107 before the 1:2 flags and orderbookSeqNo)
	//
	//     ts int64, seq int64 (nullable), fillType uint8, side uint8, liquidity uint8, price int64,
	//     size int64, fee int64, realizedPnl int64 (nullable), createdAt int64, account [32]byte,
	//     underlyingPrice int64, realizedFunding int64, flags uint8, orderbookSeqNo uint64, then the
	//     fillId, orderId, clientOrderId, tradeId, market and feeCurrency (1:2) strings
	//
	if blockSize < 107 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 6, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 5 {
		return nil
	}
	var fillTypes map[string]any = map[string]any{
		"1": "FILL",
		"2": "LIQUIDATION",
		"3": "UNWIND_TRANSFER",
		"4": "SETTLE_MARKET",
		"5": "RPI",
		"6": "BLOCK_TRADE",
	}
	var sides map[string]any = map[string]any{
		"1": "BUY",
		"2": "SELL",
	}
	var liquidities map[string]any = map[string]any{
		"1": "MAKER",
		"2": "TAKER",
	}
	var fill map[string]any = map[string]any{
		"account":          this.SbeReadAddress(frameHex, 67),
		"client_id":        this.SafeString(strings, 2),
		"created_at":       this.SbeReadTimestamp(frameHex, 59),
		"fee":              this.SbeReadDecimal(frameHex, 43),
		"fee_currency":     this.SafeString(strings, 5),
		"fill_type":        this.SbeReadEnum(frameHex, 24, fillTypes),
		"id":               this.SafeString(strings, 0),
		"liquidity":        this.SbeReadEnum(frameHex, 26, liquidities),
		"market":           this.SafeString(strings, 4),
		"order_id":         this.SafeString(strings, 1),
		"price":            this.SbeReadDecimal(frameHex, 27),
		"realized_funding": this.SbeReadDecimal(frameHex, 107),
		"realized_pnl":     this.SbeReadDecimal(frameHex, 51),
		"side":             this.SbeReadEnum(frameHex, 25, sides),
		"size":             this.SbeReadDecimal(frameHex, 35),
		"underlying_price": this.SbeReadDecimal(frameHex, 99),
	}
	if blockSize >= 116 {
		// lowercase, as the JSON feed spells fill flags
		fill["flags"] = this.SbeReadFlags(frameHex, 115, []any{"interactive", "rpi", "fastfill", "", "", "", "", "unknown"})
		fill["orderbook_seq_no"] = this.SbeReadInt64(frameHex, 116)
	}
	return fill
}
func (this *Paradex) ParseSbePosition(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// PositionEvent (templateId 22), 154-byte block
	//
	//     ts int64, seq int64, side uint8, size int64 (absolute), avgEntryPrice int64,
	//     unrealizedPnl int64, realizedPnl int64, markPrice int64 (always null), liquidationPrice
	//     int64 (nullable), leverage int64, updatedAt int64, account [32]byte, avgEntryPriceUsd
	//     int64, cost int64, costUsd int64, cachedFundingIndex int64, unrealizedFundingPnl int64,
	//     status uint8, then the market and lastFillId strings
	//
	if blockSize < 154 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 2, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 1 {
		return nil
	}
	var sides map[string]any = map[string]any{
		"1": "LONG",
		"2": "SHORT",
	}
	var statuses map[string]any = map[string]any{
		"1": "OPEN",
		"2": "CLOSED",
	}
	var side *string = this.SbeReadEnum(frameHex, 24, sides)
	var account string = this.SbeReadAddress(frameHex, 89)
	// the frame carries the size unsigned, the JSON channel signs it negative for a short
	var size any = this.SbeReadDecimal(frameHex, 25)
	if (side != nil && *side == "SHORT") && (!ccxt.IsEqual(size, "0")) {
		size = ccxt.Precise.StringNeg(size)
	}
	return map[string]any{
		"account":                 account,
		"average_entry_price":     this.SbeReadDecimal(frameHex, 33),
		"average_entry_price_usd": this.SbeReadDecimal(frameHex, 121),
		"cached_funding_index":    this.SbeReadDecimal(frameHex, 145),
		"cost":                    this.SbeReadDecimal(frameHex, 129),
		"cost_usd":                this.SbeReadDecimal(frameHex, 137),
		"id":                      account + "-" + *this.SafeString(strings, 0, ""),
		"last_fill_id":            this.SafeString(strings, 1),
		"last_updated_at":         this.SbeReadTimestamp(frameHex, 81),
		"leverage":                this.SbeReadDecimal(frameHex, 73),
		"liquidation_price":       this.SbeReadDecimal(frameHex, 65),
		"market":                  this.SafeString(strings, 0),
		"realized_positional_pnl": this.SbeReadDecimal(frameHex, 49),
		"seq_no":                  this.SbeReadInt64(frameHex, 16),
		"side":                    side,
		"size":                    size,
		"status":                  this.SbeReadEnum(frameHex, 161, statuses),
		"unrealized_funding_pnl":  this.SbeReadDecimal(frameHex, 153),
		"unrealized_pnl":          this.SbeReadDecimal(frameHex, 41),
	}
}
func (this *Paradex) ParseSbeAccount(frameHex string, blockLength int64, frameLength int64) any {
	var blockSize int64 = this.ParseToInt(blockLength)
	//
	// AccountEvent (templateId 23), 121-byte block (113 before the 1:2 lastSeenNotification)
	//
	//     ts int64, seq int64, totalCollateral int64, freeCollateral int64, initialMarginReq int64,
	//     maintenanceMarginReq int64, accountValue int64, unrealizedPnl int64 (nullable), updatedAt
	//     int64, account [32]byte, marginCushion int64, status uint8, lastSeenNotification int64,
	//     then the settlementAsset string
	//
	if blockSize < 113 {
		return nil
	}
	var strings []any = this.SbeReadVarStrings(frameHex, this.Sum(blockLength, 8), 1, frameLength)
	var stringsLength int = len(strings)
	if stringsLength < 1 {
		return nil
	}
	var statuses map[string]any = map[string]any{
		"1": "ACTIVE",
		"2": "LIQUIDATION",
	}
	var account map[string]any = map[string]any{
		"account":                        this.SbeReadAddress(frameHex, 80),
		"account_value":                  this.SbeReadDecimal(frameHex, 56),
		"free_collateral":                this.SbeReadDecimal(frameHex, 32),
		"initial_margin_requirement":     this.SbeReadDecimal(frameHex, 40),
		"maintenance_margin_requirement": this.SbeReadDecimal(frameHex, 48),
		"margin_cushion":                 this.SbeReadDecimal(frameHex, 112),
		"seq_no":                         this.SbeReadInt64(frameHex, 16),
		"settlement_asset":               this.SafeString(strings, 0),
		"status":                         this.SbeReadEnum(frameHex, 120, statuses),
		"total_collateral":               this.SbeReadDecimal(frameHex, 24),
		"updated_at":                     this.SbeReadTimestamp(frameHex, 72),
	}
	if blockSize >= 121 {
		account["last_seen_notification"] = this.SbeReadTimestamp(frameHex, 121)
	}
	return account
}
func (this *Paradex) HandleErrorMessage(client any, message any) bool {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 0,
	//         "error": {
	//             "code": -32600,
	//             "message": "invalid subscribe request",
	//             "data": "invalid channel"
	//         },
	//         "usIn": 1718179125962419,
	//         "usDiff": 76,
	//         "usOut": 1718179125962495
	//     }
	//
	var error map[string]any = ccxt.SafeMapTyped(message, "error")
	if error == nil {
		return true
	}

	{
		func(this *Paradex) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Paradex) any {
						// catch block:
						// the subscription of every request sent keeps its id, so the request this error answers is found
						// by it. A failed subscribe or auth is forgotten, so that the next watch sends it again
						var requestId *string = this.SafeString(message, "id")
						var handled bool = false
						if requestId != nil {
							var subscribeHashes []string = client.(ccxt.ClientInterface).SubscriptionKeys()
							for i := 0; i < len(subscribeHashes); i++ {
								var subscribeHash string = subscribeHashes[i]
								var subscription map[string]any = client.(ccxt.ClientInterface).SubscriptionDict(subscribeHash)
								if this.SafeString(subscription, "id") == requestId || (this.SafeString(subscription, "id") != nil && requestId != nil && *this.SafeString(subscription, "id") == *requestId) {
									handled = true
									client.(ccxt.ClientInterface).SubscriptionDel(subscribeHash)
									// watchMultiple subscribes per message hash, so the subscribe hash is what its watcher waits on
									var messageHashes []any = ccxt.SafeListTypedDefault(subscription, "messageHashes", []any{subscribeHash})
									for j := 0; j < len(messageHashes); j++ {
										client.(ccxt.ClientInterface).Reject(e, messageHashes[j])
									}
								}
							}
						}
						if !handled {
							// not a reply to a known request, every watcher on the connection gets the error,
							// and the next private watch authenticates again instead of waiting on a rejected future
							if client.(ccxt.ClientInterface).SubscriptionHas("authenticated") {
								client.(ccxt.ClientInterface).SubscriptionDel("authenticated")
							}
							client.(ccxt.ClientInterface).Reject(e)
						}
						return nil
					}(this)
				}
			}()
			// try block:
			var feedback string = this.Id + " " + this.Json(error)
			var errorCode *string = this.SafeString(error, "code")
			if errorCode != nil {
				this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
			}
			var messageString *string = this.SafeString(error, "message")
			if messageString != nil {
				this.ThrowBroadlyMatchedException(this.Exceptions["broad"], messageString, feedback)
			}
			panic(ccxt.ExchangeError(feedback))

		}(this)

	}
	return false
}
func (this *Paradex) HandleBinaryMessage(client any, message any) {
	var parsedMessage any = this.ParseSbeMessage(client, message)
	if ccxt.IsEqual(parsedMessage, nil) {
		return
	}
	this.HandleStreamMessage(client, parsedMessage)
}
func (this *Paradex) HandleMessage(client any, message map[string]any) {
	this.HandleStreamMessage(client, message)
}
func (this *Paradex) HandleStreamMessage(client any, message any) {
	if this.HandleErrorMessage(client, message) != true {
		return
	}
	//
	// auth response
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 1,
	//         "result": { "node_id": "73cf456f7cb78d59" }
	//     }
	//
	// subscription message
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "trades.ALL",
	//             "data": {
	//                 "id": "1718179273230201709233240002",
	//                 "market": "kBONK-USD-PERP",
	//                 "side": "BUY",
	//                 "size": "34028",
	//                 "price": "0.028776",
	//                 "created_at": 1718179273230,
	//                 "trade_type": "FILL"
	//             }
	//         }
	//     }
	//
	var result map[string]any = ccxt.SafeMapTyped(message, "result")
	if result != nil {
		this.HandleRequestReply(client, message)
		return
	}
	var data map[string]any = ccxt.SafeMapTyped(message, "params")
	if data != nil {
		var channel *string = this.SafeString(data, "channel")
		var parts []string = strings.Split(*channel, ".")
		var name *string = this.SafeString(parts, 0)
		var methods map[string]any = map[string]any{
			"trades":          this.HandleTrade,
			"order_book":      this.HandleOrderBook,
			"bbo":             this.HandleBidAsk,
			"markets_summary": this.HandleTicker,
			"orders":          this.HandleOrder,
			"funding_data":    this.HandleFundingRate,
			"fills":           this.HandleMyTrade,
			"positions":       this.HandlePositions,
			"account":         this.HandleBalance,
		}
		var method any = this.SafeValue(methods, name)
		if method != nil {
			ccxt.CallDynamically(method, client, message)
		}
	}
}

func NewParadex(userConfig map[string]any) *Paradex {
	p := newParadex()
	p.Init(userConfig)
	return p
}

func (this *Paradex) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

